// The code of the frame's scenes on its own screen (docs/code-editor.md): every
// scene as files (scene.json, each app's files, each code node's code), a page
// a screen, a page at a time to change, and the control plane's AI to ask for
// a new scene or a change to the one open. Everything goes through
// frameos.code, which needs the "code" permission (installing the scene is the
// owner's yes) and the frame's settings allowed on its screen.
//
// Where it is (the scene open, the file, the page, what it asked) is the
// private `spot` field, kept on disk. The files with their edits, the page
// being typed and the request are kept with frameos.remember, so they outlast
// an interpreter the frame let go. The scene settings' Code button opens it on
// a scene through the public field `open`.

const DRAFT = '\u0001draft' // the work's key for the AI's scene: no scene id has a \u0001

const WORDS = {
  no_plane: 'This frame has no control plane to ask: link it to a FrameOS backend or FrameOS Cloud.',
  ai_unavailable: "The control plane has no AI to ask (its OpenAI key, or the account's AI budget).",
  needs_owner:
    'This scene asks for more than the saved one could do (permissions or service keys). Install it from the control plane, where those are granted.',
  panel_locked: "The control plane has turned the settings on this frame's screen off.",
  rate_limited: 'Too many requests for now. Try again in a while.',
  plane_update_required: 'The control plane needs a newer FrameOS for this.',
  plane_unavailable: 'The control plane did not answer.',
  invalid_scene: 'That is not a scene this frame can hold.',
  invalid_layout: 'That layout is not one a frame can wear: a layout needs exactly one <yield />.',
  scene_requires_compilation: 'That scene needs compiling, which only a deploy does.',
  timeout: 'The AI did not finish in time.',
  no_scene: 'The AI did not deliver a scene.',
  render_failed: "The AI's scene did not render on this frame.",
  render_out_of_memory: "The AI's scene needs more memory than this frame has.",
  empty_prompt: 'Say what the scene should do first.',
  invalid_answer: 'The control plane answered with something that is not a scene.',
  no_room: 'The frame has no memory to spare for that answer.',
  failed: 'That did not work.',
}
const say = (code) => WORDS[code] || `That did not work (${code}).`

const kept = (key, empty) => {
  const value = frameos.recall(key)
  return value === undefined || value === null ? empty : value
}

// ----------------------------------------------------------------- the code

function code(op, arg) {
  try {
    return { ok: true, value: frameos.code(op, arg) }
  } catch (e) {
    return { ok: false, why: String((e && e.message) || e).replace(/^frameos\.code: /, '') }
  }
}

// ---------------------------------------------------------------- the files

// A scene as files: scene.json without its apps and its code nodes' code,
// then `<app>/<file>` for every app's files and `code/<node>.js` for every
// code node's code.
export function filesOf(scene) {
  const files = {}
  const order = ['scene.json']
  const base = {}
  for (const key of Object.keys(scene)) if (key !== 'apps') base[key] = scene[key]
  base.nodes = (Array.isArray(scene.nodes) ? scene.nodes : []).map((node) => {
    if (!node || node.type !== 'code' || !node.data || typeof node.data.codeJS !== 'string') return node
    const data = { ...node.data }
    files[`code/${node.id}.js`] = data.codeJS
    order.push(`code/${node.id}.js`)
    delete data.codeJS
    return { ...node, data }
  })
  files['scene.json'] = JSON.stringify(base, null, 2)
  const apps = scene.apps && typeof scene.apps === 'object' ? scene.apps : {}
  for (const name of Object.keys(apps)) {
    const sources = (apps[name] && apps[name].sources) || {}
    for (const file of Object.keys(sources)) {
      if (typeof sources[file] !== 'string') continue
      files[`${name}/${file}`] = sources[file]
      order.push(`${name}/${file}`)
    }
  }
  // Code nodes after the apps: an app is what a scene is mostly made of.
  const codes = order.filter((f) => f.startsWith('code/'))
  return { files, order: [...order.filter((f) => !f.startsWith('code/')), ...codes] }
}

// The files back into the scene they came from: { scene } or { error }.
export function sceneOf(original, files) {
  let scene
  try {
    scene = JSON.parse(files['scene.json'])
  } catch (e) {
    return { error: `scene.json: ${String((e && e.message) || e)}` }
  }
  if (!scene || typeof scene !== 'object' || Array.isArray(scene)) return { error: 'scene.json: not an object' }
  const apps = {}
  const was = original.apps && typeof original.apps === 'object' ? original.apps : {}
  for (const name of Object.keys(was)) {
    const app = { ...was[name], sources: { ...((was[name] && was[name].sources) || {}) } }
    for (const file of Object.keys(app.sources)) {
      const text = files[`${name}/${file}`]
      if (typeof text === 'string') app.sources[file] = text
    }
    const config = app.sources['config.json']
    if (typeof config === 'string') {
      let parsed
      try {
        parsed = JSON.parse(config)
      } catch (e) {
        return { error: `${name}/config.json: ${String((e && e.message) || e)}` }
      }
      // What the scene carries beside the files follows config.json.
      for (const key of Object.keys(app)) {
        if (key !== 'sources' && parsed && key in parsed) app[key] = parsed[key]
      }
    }
    apps[name] = app
  }
  if (Object.keys(was).length) scene.apps = apps
  scene.nodes = (Array.isArray(scene.nodes) ? scene.nodes : []).map((node) => {
    const text = node && files[`code/${node.id}.js`]
    return typeof text === 'string' ? { ...node, data: { ...node.data, codeJS: text } } : node
  })
  return { scene }
}

// What is being worked on: the scene (or the draft) as it was read, its files
// with the edits, and which files changed.
function workFor(key) {
  const work = kept('work', null)
  if (work && work.key === key) return work
  const read = key === DRAFT ? code('draft') : code('source', key)
  if (!read.ok) return { key, error: read.why }
  if (!read.value) return { key, error: key === DRAFT ? 'The draft is gone.' : 'This frame does not hold that scene.' }
  const { files, order } = filesOf(read.value)
  const fresh = { key, original: read.value, files, order, changed: [] }
  frameos.remember('work', fresh)
  return fresh
}

const changeFile = (work, file, text) => {
  work.files[file] = text
  if (!work.changed.includes(file)) work.changed.push(file)
  frameos.remember('work', work)
}

// ----------------------------------------------------------------- the spot

function readSpot(app) {
  let spot = app.state.spot
  if (typeof spot === 'string') {
    try {
      spot = JSON.parse(spot)
    } catch (e) {
      spot = null
    }
  }
  return spot && typeof spot === 'object' ? spot : {}
}
const saveSpot = (spot) => frameos.setState('spot', spot)
// A change of where it is, from a handler: kept at once, since the next
// render reads the field again.
const set = (spot, change) => {
  Object.assign(spot, change)
  saveSpot(spot)
}

// Opened from the scene settings' Code button, on that scene.
function opened(app, spot) {
  const open = app.state.open
  if (typeof open !== 'string' || !open) return
  frameos.setState('open', '')
  if (spot.id === open && !spot.draft) return
  set(spot, { view: 'code', id: open, draft: false, file: 'scene.json', page: 0, editing: null, note: '' })
  frameos.remember('work', null)
}

// ----------------------------------------------------------------- the look

function lookOf(app, context) {
  const paper = app.frame.paper === true
  const ink = paper || app.frame.color === false
  const turned = (app.frame.rotate || 0) % 180 !== 0
  const width = (context && context.imageWidth) || (turned ? app.frame.height : app.frame.width)
  const height = (context && context.imageHeight) || (turned ? app.frame.width : app.frame.height)
  // Letters keep their size wherever it shows: a bigger window shows more lines.
  const shortSide = Math.min(app.frame.width, app.frame.height) * (app.frame.scale || 1)
  const zoom = Math.max(0.75, Math.min(2.25, Math.round((shortSide / 480) * 4) / 4))
  const size = Math.round(14 * zoom)
  return {
    ink,
    width,
    height,
    size,
    rowH: Math.round(size * 1.35),
    pad: Math.round(8 * zoom),
    gap: Math.round(size * 0.5),
    barH: Math.round(size * 2.6),
    bg: ink ? 'bg-white' : 'bg-[#0d1117]',
    fg: ink ? 'text-black' : 'text-[#e6edf3]',
    dim: ink ? 'text-black' : 'text-[#7d8590]',
    line: ink ? 'border-black' : 'border-[#30363d]',
    button: ink ? 'border-2 border-black active:bg-black active:text-white' : 'bg-[#21262d] active:bg-[#30363d]',
    primary: ink ? 'bg-black text-white' : 'bg-[#1f6feb] text-white active:bg-[#388bfd]',
    field: ink ? 'border-2 border-black' : 'bg-[#161b22] focus:bg-[#1c2128]',
    picked: ink ? 'bg-black text-white' : 'bg-[#1f6feb] text-white',
  }
}

function Button({ look, label, onClick, primary = false, off = false }) {
  const h = Math.round(look.barH * 0.72)
  return (
    <div
      look={primary ? 'primary' : 'button'}
      className={`shrink-0 flex items-center justify-center h-[${h}px] px-[${look.pad + 2}px] rounded-md whitespace-nowrap ${
        off ? look.dim : primary ? look.primary : look.button
      }`}
      onClick={off ? undefined : onClick}
    >
      {label}
    </div>
  )
}

function Bar({ look, children }) {
  return (
    <div
      look="bar"
      className={`shrink-0 flex items-center gap-[${look.gap}px] h-[${look.barH}px] px-[${look.pad}px] border-b ${look.line}`}
    >
      {children}
    </div>
  )
}

const Title = ({ look, text }) => <span className="flex-1 min-w-0 truncate font-bold">{text}</span>

function Note({ look, text }) {
  if (!text) return null
  return (
    <div look="muted" className={`shrink-0 px-[${look.pad}px] py-[${Math.round(look.pad / 2)}px] border-t ${look.line} ${look.dim}`}>
      {text}
    </div>
  )
}

// ---------------------------------------------------------------- the pages

// The scenes on the frame, each a row; New scene asks the AI for one.
function Scenes({ app, look, spot, facts }) {
  const list = (Array.isArray(app.frame.scenes) ? app.frame.scenes : []).filter((s) => s && s.id)
  const fit = Math.max(1, Math.floor((look.height - look.barH * 2) / (look.rowH * 2)))
  const pages = Math.max(1, Math.ceil(list.length / fit))
  const page = Math.max(0, Math.min(spot.listPage || 0, pages - 1))
  const shown = list.slice(page * fit, page * fit + fit)
  const turn = (step) => set(spot, { listPage: Math.max(0, Math.min(pages - 1, page + step)) })
  return (
    <div className="flex flex-col flex-1 min-h-0">
      <Bar look={look}>
        <Title look={look} text="Code editor" />
        {facts.ask ? (
          <Button look={look} label="New scene with AI" primary onClick={() => set(spot, { view: 'ask', id: '', draft: false, note: '' })} />
        ) : null}
      </Bar>
      <div
        className="flex flex-col flex-1 min-h-0 overflow-hidden"
        onSwipe={(e) => turn(e.direction === 'left' || e.direction === 'up' ? 1 : e.direction === 'right' || e.direction === 'down' ? -1 : 0)}
      >
        {shown.map((scene) => (
          <div
            look="option"
            className={`shrink-0 flex flex-col justify-center h-[${look.rowH * 2}px] px-[${look.pad}px] border-b ${look.line} active:bg-[#161b22]`}
            onClick={() => {
              set(spot, { view: 'code', id: scene.id, draft: false, file: 'scene.json', page: 0, editing: null, note: '' })
              frameos.remember('work', null)
            }}
          >
            <span className="truncate">{scene.name || scene.id}</span>
            <span className={`truncate ${look.dim} text-[${Math.round(look.size * 0.8)}px]`}>{scene.id}</span>
          </div>
        ))}
        {list.length ? null : <div className={`p-[${look.pad}px] ${look.dim}`}>This frame lists no scenes here.</div>}
      </div>
      {pages > 1 ? (
        <Bar look={look}>
          <Button look={look} label="‹" off={page === 0} onClick={() => turn(-1)} />
          <span className={`flex-1 text-center ${look.dim}`}>{`${page + 1} / ${pages}`}</span>
          <Button look={look} label="›" off={page >= pages - 1} onClick={() => turn(1)} />
        </Bar>
      ) : null}
      <Note look={look} text={spot.note} />
    </div>
  )
}

// The request to the AI: a new scene, or a change to the one open.
function Ask({ look, spot, facts }) {
  const prompt = kept('prompt', '')
  const busy = facts.busy === 'ask'
  const changing = spot.id || spot.draft
  const send = () => {
    const text = kept('prompt', '').trim()
    if (!text) return set(spot, { note: say('empty_prompt') })
    const args = { prompt: text }
    if (changing) {
      const work = kept('work', null)
      const built = work && !work.error ? sceneOf(work.original, work.files) : null
      if (built && built.error) return set(spot, { note: built.error })
      if (built) args.scene = built.scene
    }
    const r = code('ask', args)
    set(spot, r.ok ? { asking: true, note: '' } : { note: r.why })
  }
  return (
    <div className="flex flex-col flex-1 min-h-0">
      <Bar look={look}>
        <Button look={look} label="Back" off={busy} onClick={() => set(spot, { view: changing ? 'code' : 'list', note: '' })} />
        <Title look={look} text={changing ? 'Ask AI for a change' : 'Ask AI for a new scene'} />
        <Button look={look} label={busy ? 'Asking…' : 'Ask'} primary off={busy} onClick={send} />
      </Bar>
      <div className={`flex flex-col flex-1 min-h-0 gap-[${look.gap}px] p-[${look.pad}px]`}>
        <span className={look.dim}>
          {changing
            ? 'What should change? The AI changes the scene as it is here, your unsaved edits included, and nothing is saved until you save its draft.'
            : 'What should the new scene show or do? Nothing is installed until you save the draft.'}
        </span>
        <textarea
          look="field"
          className={`flex-1 min-h-0 p-[${look.pad}px] rounded-md ${look.field} ${look.fg}`}
          value={prompt}
          placeholder={changing ? 'Make the text bigger and add the date' : 'A clock with the weather in Brussels'}
          onChange={(e) => frameos.remember('prompt', String(e.target.value).slice(0, 2000))}
        />
        {busy ? <span className={look.dim}>The AI is writing the scene and checking that it renders. This takes a minute or two.</span> : null}
      </div>
      <Note look={look} text={spot.note} />
    </div>
  )
}

// Rows as they show: each line of the file cut where a row ends, with the
// number of the line it starts.
function rowsOf(text, cols) {
  const rows = []
  const lines = String(text).split('\n')
  for (let i = 0; i < lines.length; i++) {
    const line = lines[i].replace(/\t/g, '  ')
    for (let at = 0; at < Math.max(1, line.length); at += cols) {
      rows.push({ n: at === 0 ? i + 1 : 0, line: i, t: line.slice(at, at + cols) })
    }
  }
  return rows
}

// A scene (or the AI's draft) as files, a page a screen.
function Code({ app, look, spot, facts }) {
  const key = spot.draft ? DRAFT : spot.id
  const work = workFor(key)
  const busy = facts.busy
  if (work.error) {
    return (
      <div className="flex flex-col flex-1 min-h-0">
        <Bar look={look}>
          <Button look={look} label="Back" onClick={() => set(spot, { view: 'list', draft: false, note: '' })} />
          <Title look={look} text={spot.id || 'Draft'} />
        </Bar>
        <div className={`p-[${look.pad}px] ${look.dim}`}>{work.error}</div>
      </div>
    )
  }
  const file = work.order.includes(spot.file) ? spot.file : work.order[0]
  const text = work.files[file] || ''
  const numberW = Math.round(look.size * 0.62 * Math.max(3, String(text.split('\n').length).length + 1))
  const cols = Math.max(12, Math.floor((look.width - look.pad * 2 - numberW) / (look.size * 0.6)))
  const rows = rowsOf(text, cols)
  const summary = spot.draft && facts.draft ? facts.draft.summary : ''
  const reserved = look.barH * 3 + (summary ? look.rowH * 2 : 0) + (spot.note ? look.rowH * 2 : 0)
  const fit = Math.max(3, Math.floor((look.height - reserved - look.pad * 2) / look.rowH))
  const pages = Math.max(1, Math.ceil(rows.length / fit))
  const page = Math.max(0, Math.min(spot.page || 0, pages - 1))
  const shown = rows.slice(page * fit, page * fit + fit)
  const turn = (step) => set(spot, { page: Math.max(0, Math.min(pages - 1, page + step)) })
  const changed = work.changed.length > 0
  const name = spot.draft ? `Draft: ${(facts.draft && facts.draft.name) || 'new scene'}` : work.original.name || spot.id

  const save = (show) => {
    const built = sceneOf(work.original, work.files)
    if (built.error) return set(spot, { note: built.error })
    const r = code('save', { scene: built.scene, show })
    set(spot, r.ok ? { saving: { id: built.scene.id, show, draft: !!spot.draft }, note: 'Saving…' } : { note: r.why })
  }

  // The page showing, in a field to change it; Done puts it back.
  if (spot.editing && spot.editing.file === file) {
    const edit = spot.editing
    return (
      <div className="flex flex-col flex-1 min-h-0">
        <Bar look={look}>
          <Button look={look} label="Cancel" onClick={() => {
            set(spot, { editing: null })
            frameos.remember('page', null)
          }} />
          <Title look={look} text={`${file}: lines ${edit.from + 1}–${edit.to}`} />
          <Button look={look} label="Done" primary onClick={() => {
            const lines = text.split('\n')
            const typed = String(kept('page', '')).split('\n')
            changeFile(work, file, [...lines.slice(0, edit.from), ...typed, ...lines.slice(edit.to)].join('\n'))
            set(spot, { editing: null })
            frameos.remember('page', null)
          }} />
        </Bar>
        <textarea
          look="field"
          className={`flex-1 min-h-0 m-[${look.pad}px] p-[${look.pad}px] rounded-md ${look.field} ${look.fg}`}
          value={kept('page', '')}
          onChange={(e) => frameos.remember('page', String(e.target.value))}
        />
      </div>
    )
  }

  return (
    <div className="flex flex-col flex-1 min-h-0">
      <Bar look={look}>
        <Button look={look} label="Back" onClick={() => set(spot, { view: 'list', draft: false, editing: null, note: '' })} />
        <Title look={look} text={changed ? `${name} •` : name} />
        {facts.ask ? <Button look={look} label="Ask AI" off={!!busy} onClick={() => set(spot, { view: 'ask', note: '' })} /> : null}
        {spot.draft ? (
          <Button look={look} label="Discard" off={!!busy} onClick={() => {
            code('clear')
            frameos.remember('work', null)
            set(spot, { view: spot.id ? 'code' : 'list', draft: false, page: 0, file: 'scene.json', note: '' })
          }} />
        ) : null}
        {facts.save ? (
          <Button look={look} label="Save" primary={changed || spot.draft} off={!!busy || (!changed && !spot.draft)} onClick={() => save(false)} />
        ) : null}
        {facts.save && spot.draft ? <Button look={look} label="Save & show" off={!!busy} onClick={() => save(true)} /> : null}
      </Bar>
      {summary ? <div className={`shrink-0 px-[${look.pad}px] py-[${Math.round(look.pad / 2)}px] ${look.dim} border-b ${look.line}`}>{summary}</div> : null}
      <Bar look={look}>
        <select
          look="field"
          className={`flex-1 min-w-0 h-[${Math.round(look.barH * 0.72)}px] px-[${look.pad}px] rounded-md ${look.field}`}
          value={file}
          onChange={(e) => set(spot, { file: String(e.target.value), page: 0 })}
        >
          {work.order.map((f) => (
            <option value={f} className={`rounded ${f === file ? look.picked : ''}`}>
              {work.changed.includes(f) ? `${f} •` : f}
            </option>
          ))}
        </select>
        <Button look={look} label="‹" off={page === 0} onClick={() => turn(-1)} />
        <span className={`shrink-0 ${look.dim}`}>{`${page + 1}/${pages}`}</span>
        <Button look={look} label="›" off={page >= pages - 1} onClick={() => turn(1)} />
        <Button look={look} label="Edit" onClick={() => {
          const from = shown.length ? shown[0].line : 0
          const to = shown.length ? shown[shown.length - 1].line + 1 : 0
          set(spot, { editing: { file, from, to } })
          frameos.remember('page', text.split('\n').slice(from, to).join('\n'))
        }} />
      </Bar>
      <div
        className={`flex flex-col flex-1 min-h-0 overflow-hidden px-[${look.pad}px] py-[${Math.round(look.pad / 2)}px]`}
        onSwipe={(e) => turn(e.direction === 'left' || e.direction === 'up' ? 1 : e.direction === 'right' || e.direction === 'down' ? -1 : 0)}
      >
        {shown.map((row) => (
          <div className={`flex shrink-0 h-[${look.rowH}px] items-center whitespace-nowrap overflow-hidden`}>
            <span className={`shrink-0 w-[${numberW}px] ${look.dim}`}>{row.n ? String(row.n) : ''}</span>
            <span>{row.t.replace(/ /g, '\u00a0')}</span>
          </div>
        ))}
      </div>
      <Note look={look} text={spot.note} />
    </div>
  )
}

// What came back since the last render: an answer from the AI, a save done.
function collect(spot, facts) {
  if (facts.busy) return
  if (spot.asking) {
    spot.asking = false
    if (facts.error) spot.note = say(facts.error)
    else if (facts.done === 'ask' && facts.draft) {
      frameos.remember('work', null)
      frameos.remember('prompt', '')
      set(spot, { view: 'code', draft: true, file: 'scene.json', page: 0, editing: null, note: '' })
    }
  }
  if (spot.saving) {
    const saving = spot.saving
    spot.saving = null
    if (facts.error) spot.note = say(facts.error)
    else if (facts.done === 'save') {
      spot.note = saving.show ? 'Saved. The frame shows it once it arrives.' : 'Saved. The frame gets it with its next push.'
      if (saving.draft) {
        code('clear')
        set(spot, { draft: false, id: saving.id })
      }
      // Read again from what the frame holds, once the push lands.
      frameos.remember('work', null)
    }
  }
}

export function get(app, context) {
  const look = lookOf(app, context)
  const spot = readSpot(app)
  opened(app, spot)
  const read = code('read')
  const facts = read.ok ? read.value : null
  let page
  if (!read.ok || !facts) {
    page = (
      <div className={`flex flex-col flex-1 p-[${look.pad * 2}px] gap-[${look.gap}px]`}>
        <span className="font-bold">Code editor</span>
        <span className={look.dim}>
          {read.ok
            ? "The code editor needs the frame's settings on its screen, and this frame has them off (or no host to read scenes from)."
            : read.why}
        </span>
      </div>
    )
  } else {
    collect(spot, facts)
    if (facts.previewOnly && !spot.note) spot.note = 'In the preview the code is read only: saving and the AI are on a frame.'
    const view = spot.view === 'ask' && facts.ask ? 'ask' : spot.view === 'code' && (spot.id || spot.draft) ? 'code' : 'list'
    page =
      view === 'ask' ? (
        <Ask look={look} spot={spot} facts={facts} />
      ) : view === 'code' ? (
        <Code app={app} look={look} spot={spot} facts={facts} />
      ) : (
        <Scenes app={app} look={look} spot={spot} facts={facts} />
      )
  }
  saveSpot(spot)
  return (
    <div look="page" className={`flex flex-col w-full h-full ${look.bg} ${look.fg} text-[${look.size}px]`}>
      {page}
    </div>
  )
}

